window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2a023c711697679e"]={"versions": [{"id": "FIG-2a023c711697679e", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Statische Software- und Hardware-Schichtenarchitektur des AUTOSAR Ethernet BSW-Stacks. Das Blockdiagramm gliedert die Ethernet-Kommunikation vertikal in die Domänen „Software“ und „Hardware“ sowie das zugrundeliegende Übertragungsmedium („Ethernet physical medium“). Innerhalb der Software-Domäne zeigt es das Ethernet Interface (EthIf) oberhalb verschiedener Ethernet-Treiber (Eth), welche die Anbindung an die Hardware-Controller (Ethernet Controller, EC) abstrahieren.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Software-Schicht umfasst:</p>\n<ul class=\"fig-list\"><li><code>Ethernet Interface</code> (EthIf): Zentrale Abstraktionsschicht, die als singuläres Modul über allen Treiberinstanzen liegt.\n</li><li><code>Ethernet Driver Vendor A</code>, <code>Ethernet Driver Vendor B</code>, <code>Ethernet Driver Vendor C</code> (Eth): Drei herstellerspezifische MCAL-/BSW-Treiberbausteine zur Hardwareansteuerung.\n</li></ul>\n<p class=\"fig-p\">Die Hardware-Schicht umfasst Ethernet-Controller verschiedener Typen:</p>\n<ul class=\"fig-list\"><li>Zwei separate Einheiten <code>EC Type A</code>, zugeordnet zu <code>Ethernet Driver Vendor A</code>.\n</li><li>Eine Einheit <code>EC Type B</code>, zugeordnet zu <code>Ethernet Driver Vendor B</code>.\n</li><li>Zwei zusammenhängende Einheiten <code>EC Type C</code>, zugeordnet zu <code>Ethernet Driver Vendor C</code>.\n</li></ul>\n<p class=\"fig-p\">Die physikalische Basis bildet das <code>Ethernet physical medium</code>. Vertikale logische Schnittstellen verbinden das Ethernet Interface mit den Treibern, die Treiber mit den jeweiligen Ethernet-Controllern und die Controller mit dem physikalischen Medium.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Schichtenmodell ohne Darstellung von Laufzeit-Sequenzen, Kontrollflüssen, API-Aufrufen oder Zustandsübergängen. Das Diagramm illustriert das strukturelle Kardinalitäts- und Multi-Vendor-Routing: Das Ethernet Interface aggregiert mehrere, potenziell von unterschiedlichen Herstellern stammende Treiber (<code>1:n</code>). Ein Treiber kann wiederum einen einzelnen Controller (<code>1:1</code>, Vendor B) oder mehrere Controller desselben Typs (<code>1:n</code>, Vendor A und Vendor C) bedienen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonische Vorgabe zur Entkopplung höherer Schichten von Hardwaredetails und herstellerspezifischen Treiberimplementierungen. Das Ethernet Interface muss so konfiguriert und implementiert sein, dass es heterogene Treiberinstanzen parallel ansprechen und Controller-Instanzen über standardisierte Schnittstellen bzw. Indizes adressieren kann. Multi-Vendor- und Multi-Channel-/Multi-Controller-Szenarien müssen ohne Modifikation der oberen Schichten unterstützt werden.</p>"}, {"id": "FIG-d21f89171f127fc3", "releases": ["R4.1.3", "R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Statische Software- und Hardware-Schichtenarchitektur des AUTOSAR Ethernet BSW-Stacks. Das Blockdiagramm gliedert die Ethernet-Kommunikation vertikal in die Domänen „Software“ und „Hardware“ sowie das zugrundeliegende Übertragungsmedium („Ethernet physical medium“). Innerhalb der Software-Domäne zeigt es das Ethernet Interface (EthIf) oberhalb verschiedener Ethernet-Treiber (Eth), welche die Anbindung an die Hardware-Controller (Ethernet Controller, EC) abstrahieren.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Software-Schicht umfasst:</p>\n<ul class=\"fig-list\"><li><code>Ethernet Interface</code> (EthIf): Zentrale Abstraktionsschicht, die als singuläres Modul über allen Treiberinstanzen liegt.\n</li><li><code>Ethernet Driver Vendor A</code>, <code>Ethernet Driver Vendor B</code>, <code>Ethernet Driver Vendor C</code> (Eth): Drei herstellerspezifische MCAL-/BSW-Treiberbausteine zur Hardwareansteuerung.\n</li></ul>\n<p class=\"fig-p\">Die Hardware-Schicht umfasst Ethernet-Controller verschiedener Typen:</p>\n<ul class=\"fig-list\"><li>Zwei separate Einheiten <code>EC Type A</code>, zugeordnet zu <code>Ethernet Driver Vendor A</code>.\n</li><li>Eine Einheit <code>EC Type B</code>, zugeordnet zu <code>Ethernet Driver Vendor B</code>.\n</li><li>Zwei zusammenhängende Einheiten <code>EC Type C</code>, zugeordnet zu <code>Ethernet Driver Vendor C</code>.\n</li></ul>\n<p class=\"fig-p\">Die physikalische Basis bildet das <code>Ethernet physical medium</code>. Vertikale logische Schnittstellen verbinden das Ethernet Interface mit den Treibern, die Treiber mit den jeweiligen Ethernet-Controllern und die Controller mit dem physikalischen Medium.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Schichtenmodell ohne Darstellung von Laufzeit-Sequenzen, Kontrollflüssen, API-Aufrufen oder Zustandsübergängen. Das Diagramm illustriert das strukturelle Kardinalitäts- und Multi-Vendor-Routing: Das Ethernet Interface aggregiert mehrere, potenziell von unterschiedlichen Herstellern stammende Treiber (<code>1:n</code>). Ein Treiber kann wiederum einen einzelnen Controller (<code>1:1</code>, Vendor B) oder mehrere Controller desselben Typs (<code>1:n</code>, Vendor A und Vendor C) bedienen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonische Vorgabe zur Entkopplung höherer Schichten von Hardwaredetails und herstellerspezifischen Treiberimplementierungen. Das Ethernet Interface muss so konfiguriert und implementiert sein, dass es heterogene Treiberinstanzen parallel ansprechen und Controller-Instanzen über standardisierte Schnittstellen bzw. Indizes adressieren kann. Multi-Vendor- und Multi-Channel-/Multi-Controller-Szenarien müssen ohne Modifikation der oberen Schichten unterstützt werden.</p>"}], "trans": [{"from": "FIG-2a023c711697679e", "to": "FIG-d21f89171f127fc3", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
